exemplos.CAMADAS:
[
 {k:"relevo", n:"RELEVO",
  novo:"Apareceram <b>3 morros</b>. Onde tem morro, o ch&#227;o &#233; alto e inclinado.",
  monta:function(){
    var d=el("div","cmcam"), i, m, mo, pc;
    for(i=0;i<MORROS.length;i++){
      m=MORROS[i];
      mo=el("i","morro");
      mo.style.left=m.l+"%"; mo.style.top=m.t+"%";
      mo.style.width=m.w+"%"; mo.style.height=m.h+"%";
      d.appendChild(mo);
      if(m.pico){
        pc=el("i","pico");
        pc.style.left=(m.l+m.w*0.3)+"%"; pc.style.top=(m.t+m.h*0.06)+"%";
        pc.style.width=(m.w*0.4)+"%"; pc.style.height=(m.h*0.22)+"%";
        d.appendChild(pc);
      }
    }
    return d;
  }},
 {k:"rios", n:"RIOS",
  novo:"Apareceram <b>2 rios</b> e um lago. Rio &#233; &#225;gua que corre sempre no mesmo lugar.",
  monta:function(){ return el("div","cmcam",RIOS); }},
 {k:"cidades", n:"CIDADES",
  novo:"Apareceram <b>5 cidades</b> (os quadradinhos). Cada uma &#233; um lugar onde mora gente.",
  monta:function(){
    var d=el("div","cmcam"), i, c;
    for(i=0;i<CIDADES.length;i++){
      c=el("i","cid","<i></i>");
      c.style.left=CIDADES[i][0]+"%"; c.style.top=CIDADES[i][1]+"%";
      d.appendChild(c);
    }
    return d;
  }}
]

